import{_ as l,l as n,o as e,c as i,v as r,p as s,x as t,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"底层设计与二次电子","description":"","frontmatter":{"title":"底层设计与二次电子","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/underlayer-secondary-electron.md","filePath":"litho/underlayer-secondary-electron.md","lastUpdated":1789023840000}'),c={name:"litho/underlayer-secondary-electron.md"};function u(E,a,_,A,f,m){const o=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="底层设计与二次电子" tabindex="-1">底层设计与二次电子 <a class="header-anchor" href="#底层设计与二次电子" aria-label="Permalink to &quot;底层设计与二次电子&quot;">​</a></h1><div class="epigraph"><p>薄胶的界面是电子的出入口。底层可以提高二次电子产额来补灵敏度，也会把底部模糊和 footing 写成侧壁。</p><footer>—— 据 Naulleau 二次电子模糊；Kozawa 电离产酸；Levinson 底层功能</footer></div><p><a href="/litho/euv-resist-absorption">上一课</a>把膜厚和吸收系数锁在一起。缺口是膜下面那一层：事件不仅生于胶内吸收，也生于底层射上来的二次电子。<a href="/litho/euv-underlayer">EUV 底层</a> 已列功能栈；<a href="/litho/euv-secondary-electron">二次电子产额</a> 已给产额语言。本课把两者收成设计旋钮。高 NA 下这张薄栈如何转印，留给[下一课](/litho/high-na-pattern-transfer）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>吸收课假设光子在胶内变成事件。胶只有十几纳米时，界面占比巨大：底层高 Z 或高密度会抬二次电子产额，等效增加底部剂量，灵敏度「免费」上升；同时底部模糊核加厚，清底与 footing 和光学离焦同貌。设计缺口是：用底层补 \\(\\bar N\\) 时，能补多少、侧壁还能不能立。不是再列黏附、平面化、硬掩模清单。</p><p>CAR 对底层酸碱敏感，衬底淬灭出 footing；金属氧化物对界面黏附和显影钻蚀敏感。二次电子是第三条、EUV 特有的耦合。</p><p><span class="marginnote">底层不是光学透明垫片。换 underlayer 等于换胶模型的界面源项，OPC 要紧凑模型重校准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验：同一胶只换底层，看 \\(E_0\\)、侧壁、LER 高频和孔缺失。产额升而剖面倒锥，说明底部事件过密。产额低而膜又薄，随机先爆——应加 \\(\\alpha\\) 或 \\(D\\)，而不是只怪 SMO。栈：黏附层、电子调节层、硬掩模可以是一层或两层，电子调节与硬掩模的元素选择往往冲突（高 Z 利电子、未必利蚀刻）。</p><p>与吸收：胶内 \\(\\alpha t\\) 与界面产额是两源。模型要能分开，否则加剂量和换底层在仿真里不可区分。</p><h3 id="电子调节与硬掩模常常打架" tabindex="-1">电子调节与硬掩模常常打架 <a class="header-anchor" href="#电子调节与硬掩模常常打架" aria-label="Permalink to &quot;电子调节与硬掩模常常打架&quot;">​</a></h3><p>高 Z 底层利二次电子和灵敏度，干法选择比和金属沾污未必合格。含硅硬掩模利转印，电子产额可能不够。两层栈把功能拆开：薄电子层贴胶、厚硬掩模在下。涂布混合、烘烤互扩散会把两层重新搅在一起，窗口实验必须声明栈，不能只报「一种底层」。</p>',12)),(e(),s(p,null,{default:t(()=>[h(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PH%5B%22%E8%83%B6%E5%86%85%E5%90%B8%E6%94%B6%22%5D%20--%3E%20EV%5B%22%E5%8C%96%E5%AD%A6%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20UL%5B%22%E5%BA%95%E5%B1%82%E4%BA%8C%E6%AC%A1%E7%94%B5%E5%AD%90%22%5D%20--%3E%20EV%0A%20%20EV%20--%3E%20SENS%5B%22%E7%81%B5%E6%95%8F%E5%BA%A6%22%5D%0A%20%20UL%20--%3E%20BLUR%5B%22%E5%BA%95%E9%83%A8%E6%A8%A1%E7%B3%8A%20%2F%20footing%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>92 eV 光子在底层电离，电子级联，射程纳米量级，一部分越过界面进入胶。Naulleau 的模糊核、Kozawa 的电离产酸，在界面处变成轴向不对称：底部事件密度高于按胶内 Beer 定律的外推。热化距离随材料变，本课不编射程表，只要求资格认证声明底层。氢和真空污染课的出气，底层也是源之一，设计还要低放气。</p><p><span class="marginnote">「更敏的底层」可能是电子灌入，也可能是界面不淬灭酸。要用剖面和随机曲线拆，不能只看 Esize。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写干法如何把 15 nm 浮雕传到硬掩模，下一课才写高 NA 薄胶转印。不重写 BARC 驻波——EUV 驻波不是第一理由。界面电子是轴向不对称模糊，不能用对称高斯酸核代替。出处：Naulleau；Kozawa；Levinson；底层与产额课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>底层二次电子是薄胶灵敏度的设计旋钮，也是底部模糊源。</li><li>与胶内吸收分源建模；换底层要重校准 OPC。</li><li>下一课：这张薄潜像怎样变成可蚀刻的硬掩模图形。</li><li>出处：Naulleau、Kozawa、Levinson。</li></ul>',7))])}const P=l(c,[["render",u]]);export{b as __pageData,P as default};
